COMMENT ON COLUMN VENDOR."NAME" IS 'Company name.';
COMMENT ON COLUMN VENDOR.CREDITRATING IS 'Rating of credit.';
ALTER TABLE VENDOR MODIFY (CREDITRATING ANNOTATIONS (ADD value_description 'commonsense evidence: 1 = Superior, 2 = Excellent, 3 = Above average, 4 = Average, 5 = Below average. commonsense evidence:1, 2, 3 can represent good credit, 4 is average credit, 5 is bad credit.'));
COMMENT ON COLUMN VENDOR.PREFERREDVENDORSTATUS IS 'Preferred Vendor Status';
ALTER TABLE VENDOR MODIFY (PREFERREDVENDORSTATUS ANNOTATIONS (ADD value_description 'commonsense evidence: 0 = Do not use if another vendor is available. 1 = Preferred over other vendors supplying the same product.'));
