COMMENT ON COLUMN VENDOR.MODIFIEDDATE IS 'Date and time the record was last updated.';
ALTER TABLE VENDOR MODIFY (MODIFIEDDATE ANNOTATIONS (ADD value_description 'Default: getdate()'));
